11	const ForgotPassword = () => {
12	  const navigate = useNavigate();
13	  const { user, loading } = useAuth();
14	
15	  const [email, setEmail] = useState("");
16	  const [submitting, setSubmitting] = useState(false);
17	  const [sent, setSent] = useState(false);
18	
19	  // Redirect if already authenticated
20	  useEffect(() => {
21	    if (!loading && user) {
22	      navigate("/dashboard", { replace: true });
23	    }
24	  }, [user, loading, navigate]);
25	
26	  const handleSubmit = async (e: React.FormEvent) => {
27	    e.preventDefault();
28	
29	    if (!email.trim()) {
30	      toast.error("Email is required.");
31	      return;
32	    }
33	    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
34	      toast.error("Enter a valid email address.");
35	      return;
36	    }
37	
38	    setSubmitting(true);
39	
40	    const { error } = await supabase.auth.resetPasswordForEmail(email.trim(), {
41	      redirectTo: `${window.location.origin}/reset-password`,
42	    });
43	
44	    setSubmitting(false);
45	
46	    if (error) {
47	      toast.error(error.message ?? "Failed to send reset email. Please try again.");
48	      return;
49	    }
50	
51	    setSent(true);
52	  };
53	
54	  return (
55	    <div className="flex min-h-screen items-center justify-center bg-background px-4">
56	      <div className="w-full max-w-sm">
57	        {/* Logo */}
58	        <Link to="/" className="mb-10 flex items-center gap-2">
59	          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary">
60	            <Bot className="h-4 w-4 text-white" />
61	          </div>
62	          <span className="text-lg font-bold tracking-tight text-foreground">CROBOT</span>
63	        </Link>
64	
65	        {sent ? (
66	          /* Success state */
67	          <div className="space-y-4">
68	            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/8">
69	              <Mail className="h-6 w-6 text-primary" />
70	            </div>
71	            <h1 className="text-2xl font-bold text-foreground">Check your email</h1>
72	            <p className="text-sm text-muted-foreground">
73	              We sent a password reset link to{" "}
74	              <span className="font-medium text-foreground">{email}</span>.
75	              The link expires in 1 hour.
76	            </p>
77	            <p className="text-xs text-muted-foreground">
78	              Didn't receive it? Check your spam folder or{" "}
79	              <button
80	                type="button"
81	                className="text-primary hover:underline"
82	                onClick={() => setSent(false)}
83	              >
84	                try a different email
85	              </button>
86	              .
87	            </p>
88	            <Button
89	              variant="outline"
90	              className="mt-2 w-full border-border/50"
91	              onClick={() => navigate("/login")}
92	            >
93	              Back to login
94	            </Button>
95	          </div>
96	        ) : (
97	          /* Form state */
98	          <div className="space-y-4">
99	            <div>
100	              <h1 className="text-2xl font-bold text-foreground">Reset your password</h1>
101	              <p className="mt-1.5 text-sm text-muted-foreground">
102	                Enter your account email and we'll send you a reset link.
103	              </p>
104	            </div>
105	
106	            <form onSubmit={handleSubmit} className="space-y-4">
107	              <div className="space-y-2">
108	                <Label htmlFor="fp-email">Email address</Label>
109	                <Input
110	                  id="fp-email"
111	                  type="email"
112	                  placeholder="you@company.com"
113	                  value={email}
114	                  onChange={(e) => setEmail(e.target.value)}
115	                  className="border-border/50"
116	                  required
117	                  disabled={submitting}
118	                  autoFocus
119	                />
120	              </div>
121	
122	              <Button
123	                type="submit"
124	                className="w-full py-5 font-semibold"
125	                disabled={submitting}
126	              >
127	                {submitting ? (
128	                  <span className="flex items-center gap-2">
129	                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-primary-foreground border-t-transparent" />
130	                    Sending…
131	                  </span>
132	                ) : (
133	                  "Send reset link"
134	                )}
135	              </Button>
136	            </form>
137	
138	            <Link
139	              to="/login"
140	              className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-foreground transition-colors"
141	            >
142	              <ArrowLeft className="h-4 w-4" />
143	              Back to login
144	            </Link>
145	          </div>
146	        )}
147	      </div>
148	    </div>
149	  );
150	};
151	
152	export default ForgotPassword;
